namespace ghidra.app.plugin.core.symboltree.actions;








using docking.action;
using docking.action;
using docking.widgets.tree;
using ghidra.app.plugin.core.symboltree;
using ghidra.app.plugin.core.symboltree;
using ghidra.app.plugin.core.symboltree.nodes;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using resources;

public class DeleteAction : SymbolTreeContextAction {

	private static Icon DELETE_ICON = Icons.DELETE_ICON;

	private SymbolTreePlugin plugin;

	public DeleteAction(SymbolTreePlugin plugin) : base("Delete Symbols", plugin.getName())
    {
		this.plugin = plugin;

		setPopupMenuData(new MenuData(new string[] { "Delete" }, DELETE_ICON, "xxx",
			MenuData.NO_MNEMONIC, "2"));
		setKeyBindingData(new KeyBindingData(KeyEvent.VK_DELETE, 0));
	}

	/* @Override */
	public bool isEnabledForContext(SymbolTreeActionContext context) {
		TreePath[] selectionPaths = context.getSelectedSymbolTreePaths();
		if (selectionPaths.length == 0) {
			return false;
		}

		foreach (TreePath treePath in selectionPaths) {
			object @object = treePath.getLastPathComponent();
			if (!(@object is SymbolNode) &&
				!(@object is OrganizationNode)) {
				// can only delete symbol nodes or the fake organization nodes, as those are just 
				// small groups of symbols
				return false;
			}
		}

		return true;
	}

	/* @Override */
	public void actionPerformed(SymbolTreeActionContext context) {
		TreePath[] selectionPaths = context.getSelectedSymbolTreePaths();
		List<SymbolTreeNode> nodes = getNodes(selectionPaths);
		Program program = plugin.getProgram();
		program.withTransaction("Delete Symbols(s)", () => {
			foreach (SymbolTreeNode node in nodes) {
				Symbol symbol = node.getSymbol();
				symbol.delete();
				node.getParent().removeNode(node);
			}
		});
	}

	private List<SymbolTreeNode> getNodes(TreePath[] paths) {
		List<SymbolTreeNode> nodes = new();
		foreach (TreePath treePath in paths) {
			object @object = treePath.getLastPathComponent();
			if (@object is SymbolNode symbolNode) {
				nodes.add(symbolNode);
			}
			else if (@object is OrganizationNode orgNode) {
				getNodes(orgNode, nodes);
			}
		}
		return nodes;
	}

	private void getNodes(OrganizationNode orgNode, List<SymbolTreeNode> nodes) {
		List<GTreeNode> children = orgNode.getChildren();
		foreach (GTreeNode node in children) {
			if (node is SymbolNode symbolNode) {
				nodes.add(symbolNode);
			}
			else if (node is OrganizationNode childOrgNode) {
				getNodes(childOrgNode, nodes);
			}

		}
	}
}
